def one(oid,rx,ex=None):
    r=ORG[str(oid)]
    for x in r['items']:
        if re.search(rx,x['title'] or '',re.I) and not (ex and re.search(ex,x['title'],re.I)) and (lib._num(x['price']) or 0)>1: return r,x
    raise SystemExit(f'нет {oid} {rx}')
def SUM2(oid,rxa,rxb,exa=None,exb=None):
    r,a=one(oid,rxa,exa); _,b=one(oid,rxb,exb)
    pa,pb=lib._num(a['price']),lib._num(b['price'])
    return {'company':r['meta']['title'],'url':r['url'],'price':f"{a['price']} ₽ и {b['price']} ₽",'za_chto':f"{a['title'].strip()} + {b['title'].strip()}; в расчёте 2 рычага и 2 амортизатора, только работа",'v':2*pa+2*pb}

